import { reviewEligibility } from './outputs.mjs';
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const base = id => '/transcription/' + encodeURIComponent(id);
const clock = seconds => { const s = Math.max(0, Math.floor(Number(seconds) || 0)); return [Math.floor(s / 3600), Math.floor(s / 60) % 60, s % 60].map(v => String(v).padStart(2, '0')).join(':'); };

const stageLabels = {join:'Joining conversation', queued:'Waiting to start', normalize:'Preparing audio', transcribe:'Transcribing', diarize:'Separating speakers', merge:'Combining transcript', ingest:'Saving transcript'};
export function reviewIssues(result) {
  return (result.segments || []).flatMap((segment,index,all)=>{
    const reasons=[];
    if(!segment.speaker)reasons.push('Missing speaker');
    if(segment.confidence_unavailable|| (Number.isFinite(segment.avg_logprob)&&segment.avg_logprob < -1))reasons.push('Unclear speech');
    if(!reasons.includes('Unclear speech')&&(segment.words||[]).some(w=>Number.isFinite(w.probability)&&w.probability<0.35))reasons.push('Unclear speech');
    for(const flag of result.metadata?.quality_flags||[]){if(Number(flag.start)<segment.end&&Number(flag.end)>segment.start){const reason=flag.kind==='confidence'?'Unclear speech':'Possible repetition';if(!reasons.includes(reason))reasons.push(reason)}}
    const text=segment.text.trim();
    if(text && ((all[index-1]?.text.trim()===text&&all[index+1]?.text.trim()===text)||/(.{4,80}?)\1\1/u.test(text)))reasons.push('Repeated text');
    return reasons.length?[{index,start:segment.start,end:segment.end,reasons}]:[];
  });
}
function progressLine(job){
  const steps=[['join','Joining'],['diarize','Detecting speakers'],['transcribe','Transcribing'],['done','Ready']];
  const current=job.state==='done'?3:job.stage==='transcribe'?2:['merge','ingest','filing'].includes(job.stage)?2:job.stage==='diarize'?1:0;
  return `<ol class="progress-line" data-progress-line aria-label="Processing progress">${steps.map(([key,label],i)=>`<li data-progress-step="${i}" ${i===current?'aria-current="step"':''}>${label}</li>`).join('')}</ol>`;
}
const needsModelAccess = job => /(?:gated repo|authorized list|access.*restricted)/i.test(job.error || '');
export const cleanRecordingTitle = value => String(value||'Recording').replace(/\.[a-z0-9]{2,5}$/i,'').replace(/^TX00_(MIC\d+)_([0-9]{4})([0-9]{2})([0-9]{2})_([0-9]{2})([0-9]{2})([0-9]{2})_orig$/i,(_,mic,y,m,d,h,n)=>`${mic} · ${y}-${m}-${d} ${h}:${n}`).replace(/_/g,' ').replace(/\s+/g,' ').trim();
export const suggestedConversationTitle = filename => {
 const match=filename.match(/^TX00_MIC\d+_(\d{4})(\d{2})(\d{2})_/i);
 return match?`Conversation · ${match[1]}-${match[2]}-${match[3]}`:cleanRecordingTitle(filename);
};
const recordingCategory = job => job.state==='saved'?'parts':job.state==='failed'||job.transcriptError?'attention':job.transcriptReady?'ready':'processing';
const recordingMeta = job => [job.partCount>1?`${job.partCount} parts`:null,job.durationSeconds?`${Math.round(job.durationSeconds/60)} min`:null,job.speakerCount?`${job.speakerCount} speakers`:null,job.reviewStatus==='reviewed'?'Reviewed':job.transcriptReady?'Unreviewed':null,job.saved?.state==='saved'?'Saved to Mag':null,...(job.availableLanguages||[]).map(l=>l.toUpperCase()),job.export?.state==='failed'?'Sync needs retry':null].filter(Boolean).join(' · ');
export function renderLocalJob(job) {
 const category=recordingCategory(job);
 const status=job.state==='saved'?'Saved · ready to start':job.state==='running'?(stageLabels[job.stage]||job.stage||'Preparing recording'):job.transcriptError?'Transcript unavailable':job.state==='done'?'Transcript ready':needsModelAccess(job)?'Speaker model access required':(job.error||'Could not transcribe this recording').split('\n')[0].slice(0,160);
 const date=job.started&&!Number.isNaN(Date.parse(job.started))?new Intl.DateTimeFormat('en',{month:'short',day:'numeric',timeZone:'Asia/Hong_Kong'}).format(new Date(job.started)):'';
 const title=cleanRecordingTitle(job.story||job.file), parts=job.libraryParts||[];
 const mainAction=job.state==='running'?`<a class="mini primary-row-action" href="${base(job.id)}/view">View progress</a>`:job.transcriptReady?`<a class="mini primary-row-action" aria-label="Read transcript: ${esc(title)}" href="${base(job.id)}/view">Open →</a>`:job.state==='saved'?`<button class="mini primary-row-action" type="button" data-job-start="${esc(job.id)}">Start</button>`:(job.state==='failed'||job.transcriptError)?`<button class="mini primary-row-action" type="button" data-job-retry="${esc(job.id)}">Resume</button>`:'';
 return `<div class="dropped" data-local-job="${esc(job.id)}" data-state="${esc(job.state)}" data-recording-category="${category}"><label class="recording-select"><input type="checkbox" data-join-recording="${esc(job.id)}" data-recording-name="${esc(job.file||job.story)}" aria-label="Select ${esc(job.story)}" ${job.sourceJobs?.length||job.sources?.length||job.state==='running'?'disabled':''}></label><span class="recording-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M5 9v6m4-10v14m6-12v10m4-8v6"/></svg></span><div class="recording-copy"><strong title="${esc(job.file||job.story)}">${esc(title)}</strong><span data-job-status role="status">${esc(status)}</span><span class="conversation-meta" data-job-metadata>${esc(recordingMeta(job))}</span>${parts.length?`<details class="conversation-parts"><summary>${parts.length} recording parts</summary><ol>${parts.map(part=>`<li title="${esc(part.file)}">${esc(part.file||part.story)}</li>`).join('')}</ol></details>`:''}${job.state==='failed'&&job.error?`<details class="recording-error"><summary>Error details</summary><p>${esc(job.error)}</p></details>`:''}</div><span class="recording-date">${esc(date)}</span><span data-job-actions>${mainAction}</span></div>`;
}

export function renderRecordings(jobs=[],remote=false) {
  const byId=new Map(jobs.map(job=>[job.id,job]));
  const grouped=new Set(jobs.flatMap(job=>job.sourceJobs||[]));
  jobs=jobs.filter(job=>!grouped.has(job.id)).map(job=>({...job,partCount:job.partCount||job.sourceJobs?.length||1,libraryParts:(job.sourceJobs||[]).map(id=>byId.get(id)).filter(Boolean)})).sort((a,b)=>(a.state==='running'?0:1)-(b.state==='running'?0:1));
  const counts = {all:jobs.length,ready:0,processing:0,attention:0,parts:0};
  for(const job of jobs)counts[recordingCategory(job)]++;
  const blocked = jobs.some(needsModelAccess);
  return `<main class="recordings-page"><header class="library-header"><div><p class="eyebrow">Local transcription</p><h1>Recordings</h1></div><a class="library-link" href="/">Story approvals ↗</a></header>
<section class="upload-group" aria-label="Add recordings"><form class="upload card"><label class="zone"><input aria-label="Choose audio or video files" type="file" name="file" multiple accept="audio/*,video/*,.m4a,.mp3,.wav,.mov,.mp4"><span class="upload-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 16V4m-4 4 4-4 4 4M5 15v5h14v-5"/></svg></span><span class="big">Drop recordings <span class="drop-or">or</span> <span class="choose-files">choose files</span></span><span class="format-hint">M4A, MP3, WAV, MP4 and more · multiple files welcome</span></label><div class="upload-settings" data-upload-settings hidden><div class="other"><label for="recording-name">Recording name <span>(optional)</span></label><input id="recording-name" name="story" placeholder="Recording name (optional)" maxlength="80"></div><label class="join-upload-option"><input type="checkbox" data-join-upload checked><span><strong>One conversation</strong><small>Join files in filename order</small></span></label></div><section class="upload-preview" data-upload-preview hidden><p class="meta" data-upload-summary role="status"></p><ol data-upload-order></ol><button type="button" class="save" data-upload-start disabled>Start</button><button type="button" class="mini" data-upload-cancel>Clear</button><span role="status" data-upload-status></span></section><div class="queue" aria-live="polite"></div></form>
<div class="library-note"><span>Processed on this Mac. Original recordings stay saved.</span>${remote?'':'<a href="/drop" data-open>Open folder ↗</a>'}</div></section>
${blocked ? '<aside class="setup-notice"><div><strong>Speaker separation needs setup</strong><p>Community-1 model access is required. Recordings are saved and can be retried after setup.</p></div><a href="https://huggingface.co/pyannote/speaker-diarization-community-1" target="_blank" rel="noopener">Model setup ↗</a></aside>' : ''}
<section class="recording-library" aria-label="Your recordings"><div class="library-toolbar"><div class="library-title"><h2>Conversations</h2><p>Transcripts, languages and saved files together.</p></div><button class="mini" type="button" data-select-mode aria-pressed="false">Select files</button></div><div class="bulk-toolbar" data-bulk-toolbar hidden><span data-selection-count>0 selected</span><button class="mini" type="button" data-join-prepare disabled>Join selected</button><button class="mini" type="button" data-clear-selection>Clear selection</button></div><form data-join-form hidden><label>Conversation name<input name="story" required maxlength="80" placeholder="Conversation name"></label><p class="meta">Automatically ordered by filename. One audio file, one speaker map, one transcript.</p><ol data-join-order></ol><button type="submit" class="save">Join & transcribe</button><button type="button" class="mini" data-join-cancel>Cancel</button><span role="status" aria-live="polite"></span></form><nav class="recording-filters" aria-label="Filter recordings">${[['all','All'],['ready','Ready'],['processing','Processing'],['attention','Needs attention'],...(counts.parts?[['parts','Saved parts']]:[])].map(([value,label])=>`<button type="button" data-recording-filter="${value}" aria-pressed="${value==='all'}">${label}<span>${counts[value]}</span></button>`).join('')}</nav><div class="recording-list">${jobs.map(renderLocalJob).join('')}</div><p class="library-empty" data-recordings-empty role="status" aria-live="polite" ${jobs.length?'hidden':''}>${jobs.length?'No recordings in this view.':'Your transcripts will appear here after you drop a recording.'}</p></section></main>`;
}

