  const durations=await Promise.all(pendingFiles.map(fileDuration));if(token!==preparingFiles)return;const known=durations.filter(v=>v!==null);summary.textContent=pendingFiles.length+' '+(pendingFiles.length===1?'file':'files')+' · '+(known.length===durations.length?new Date(known.reduce((a,b)=>a+b,0)*1000).toISOString().slice(11,19)+' total':'duration unavailable for some files')+' · filename order';button.disabled=false;
